/// Longest generated sequence.
const MAX_STEPS: usize = 100;
/// Seed of the document actor's id streams.
const SEED: u64 = 42;
/// Where failing seeds are kept (committed).
const REGRESSIONS: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/proptest-regressions/registry_props.txt"
);
/// Sequences of the deterministic coverage run. Each new command shifts the fixed seed's
/// stream; at 48 the export queue and lock commands dropped coverage to 93%, and at 128 the
/// three import commands of ADR-0035 dropped it to 94.3%. Commands whose
/// preconditions are rare (keyframes to move, a proxy to delete) want strategies that set
/// them up rather than more cases (issue #184). Raised from 160 to 176 with the two commands
/// of issue #222 (`timeline.update_marker`, `item.set_label_color`), and to 192 with them and
/// `edit.set_history_limit` together.
const COVERAGE_CASES: u32 = 192;

static REGISTRY: LazyLock<Arc<Registry>> = LazyLock::new(|| Arc::new(testing::registry()));

// ----- inputs --------------------------------------------------------------------------------

#[derive(Clone, Debug)]
enum Start {
    /// `Project::new`: the sequence starts with `project.new`, imports and inserts.
    Empty,
    /// The WP-1B.06 edit fixture, built with commands.
    Fixture,
    /// An `arb_project` document.
    Generated(Box<Project>),
}

fn arb_start() -> impl Strategy<Value = Start> {
    prop_oneof![
        1 => Just(Start::Empty),
        1 => Just(Start::Fixture),
        3 => cutweave_model::testing::arb_project().prop_map(|p| Start::Generated(Box::new(p))),
    ]
}

#[derive(Clone, Copy, Debug)]
enum Action {
    /// A generated request; `seed` drives the generator, `in_tx` runs it in the actor's open
    /// transaction (if it has one and the entry can run in one).
    Request { seed: u64, in_tx: bool },
    /// The actor's connection closes: its open transaction rolls back.
    Disconnect,
    /// 31 s pass: an idle gesture expires.
    Idle,
}

#[derive(Clone, Copy, Debug)]
struct Step {
    agent: bool,
    action: Action,
}

fn arb_step() -> impl Strategy<Value = Step> {
    let action = prop_oneof![
        40 => (any::<u64>(), prop::bool::weighted(0.75))
            .prop_map(|(seed, in_tx)| Action::Request { seed, in_tx }),
        1 => Just(Action::Disconnect),
        1 => Just(Action::Idle),
    ];
    (prop::bool::weighted(0.2), action).prop_map(|(agent, action)| Step { agent, action })
}

fn arb_case() -> impl Strategy<Value = (Start, Vec<Step>)> {
    (arb_start(), vec(arb_step(), 1..=MAX_STEPS))
}

fn splitmix(mut z: u64) -> u64 {
    z = z.wrapping_add(0x9E37_79B9_7F4A_7C15);
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

/// The request `seed` picks for `doc` (deterministic: a shrunk sequence replays exactly).
fn generate(registry: &Registry, doc: &Project, seed: u64) -> (String, Value) {
    let mut bytes = [0_u8; 32];
    let mut s = seed;
    for chunk in bytes.chunks_mut(8) {
        s = splitmix(s);
        chunk.copy_from_slice(&s.to_le_bytes());
    }
    let config = Config {
        failure_persistence: None,
        ..Config::default()
    };
    let mut runner =
        TestRunner::new_with_rng(config, TestRng::from_seed(RngAlgorithm::ChaCha, &bytes));
    arb_command_from(registry, doc)
        .new_tree(&mut runner)
        .expect("the strategies never reject")
        .current()
}

// ----- statistics ----------------------------------------------------------------------------

/// Outcomes per entry name (`ok` or the error code).
#[derive(Default)]
struct Stats {
    calls: BTreeMap<String, BTreeMap<&'static str, usize>>,
    cases: usize,
    requests: usize,
    history_checks: usize,
    max_items: usize,
}

impl Stats {
    fn record(&mut self, name: &str, outcome: Result<(), &CmdError>) {
        let code = outcome.map_or_else(CmdError::code, |()| "ok");
        *self
            .calls
            .entry(name.to_owned())
            .or_default()
            .entry(code)
            .or_default() += 1;
        self.requests += 1;
    }

    fn ok(&self, name: &str) -> usize {
        self.calls
            .get(name)
            .and_then(|c| c.get("ok"))
            .copied()
            .unwrap_or(0)
    }

    /// `(exercised, total)`: entries with at least one success, of every covered entry.
    fn coverage(&self, registry: &Registry) -> (usize, usize) {
        let names: Vec<&str> = testing::covered(registry)
            .map(cutweave_commands::Entry::name)
            .collect();
        let exercised = names.iter().filter(|n| self.ok(n) > 0).count();
        (exercised, names.len())
    }

    fn report(&self, registry: &Registry) -> String {
        const CODES: [&str; 6] = [
            "ok",
            "invalid",
            "not_found",
            "locked",
            "conflict",
            "unsupported",
        ];
        let (exercised, total) = self.coverage(registry);
        let permille = exercised * 1000 / total.max(1);
        let mut out = format!(
            "strategy coverage: {exercised}/{total} registered non-view entries applied \
             successfully at least once ({}.{}%) in {} sequences, {} requests, {} undo/redo \
             round trips; largest document: {} items\n",
            permille / 10,
            permille % 10,
            self.cases,
            self.requests,
            self.history_checks,
            self.max_items,
        );
        let _ = write!(out, "{:<22}", "entry");
        for code in CODES {
            let _ = write!(out, "{code:>12}");
        }
        out.push('\n');
        for entry in testing::covered(registry) {
            let name = entry.name();
            let calls = self.calls.get(name);
            let _ = write!(out, "{name:<22}");
            for code in CODES {
                let n = calls.and_then(|c| c.get(code)).copied().unwrap_or(0);
                let _ = write!(out, "{n:>12}");
            }
            if self.ok(name) == 0 {
                out.push_str("   <- never succeeded");
            }
            out.push('\n');
        }
        out
    }
}

// ----- the harness ---------------------------------------------------------------------------

/// What a request is checked against.
#[derive(Clone, Debug, PartialEq)]
struct Obs {
    rev: Rev,
    committed_rev: Rev,
    live: Project,
    committed: Project,
}

/// A successful request.
struct Done {
    output: Value,
    /// `None` for `media.import` and `job.*` (engine commands the actor does not run).
    applied: Option<Applied>,
}

/// Registers `media.import` batches as one transaction of the importing actor, on a connection
/// of its own (so it never collides with the actor's open transaction). `media.import` hands
/// it only the readable files (the others are in `failed[]`) and maps a `/paths/<i>` error
/// pointer from the batch index back to the request index.
struct ImportSink {
    state: Arc<Mutex<DocState>>,
    ctx: ActorCtx,
}

impl MediaSink for ImportSink {
    fn register(&mut self, batch: Vec<MediaRegister>) -> Result<Vec<MediaRegistered>, CmdError> {
        let mut s = self.state.lock().unwrap();
        let tx = s.begin_tx(&self.ctx, TxKind::Batch, "Import media")?.id;
        let mut out = Vec::with_capacity(batch.len());
        for (i, r) in batch.iter().enumerate() {
            let params = serde_json::to_value(r).unwrap();
            let submit = Submit::new(self.ctx.clone(), "media.register", params).in_tx(tx);
            match s.submit(submit) {
                Ok(a) => out.push(serde_json::from_value(a.output).unwrap()),
                Err(e) => {
                    s.cancel_tx(&self.ctx, tx).unwrap();
                    return Err(match e {
                        CmdError::Invalid { path, msg } => {
                            CmdError::invalid(format!("/paths/{i}{path}"), msg)
                        }
                        other => other,
                    });
                }
            }
        }
        if let Err(e) = s.commit_tx(&self.ctx, tx) {
            let _ = s.cancel_tx(&self.ctx, tx);
            return Err(e);
        }
        Ok(out)
    }

    fn register_tree(&mut self, tree: MediaRegisterTree) -> Result<MediaTreeRegistered, CmdError> {
        let mut s = self.state.lock().unwrap();
        let tx = s.begin_tx(&self.ctx, TxKind::Batch, "Import folder")?.id;
        let params = serde_json::to_value(&tree).unwrap();
        let submit = Submit::new(self.ctx.clone(), "media.register_tree", params).in_tx(tx);
        match s.submit(submit) {
            Ok(a) => {
                let out = serde_json::from_value(a.output).unwrap();
                if let Err(e) = s.commit_tx(&self.ctx, tx) {
                    let _ = s.cancel_tx(&self.ctx, tx);
                    return Err(e);
                }
                Ok(out)
            }
            Err(e) => {
                s.cancel_tx(&self.ctx, tx).unwrap();
                Err(e)
            }
        }
    }

    fn slideshow(&mut self, batch: SlideshowBatch) -> Result<SlideshowPlaced, CmdError> {
        let mut s = self.state.lock().unwrap();
        let tx = s.begin_tx(&self.ctx, TxKind::Batch, "Import slideshow")?.id;
        let mut steps = TxSteps {
            state: &mut s,
            ctx: &self.ctx,
            tx,
        };
        match place_slideshow(&mut steps, &batch) {
            Ok(placed) => {
                if let Err(e) = s.commit_tx(&self.ctx, tx) {
                    let _ = s.cancel_tx(&self.ctx, tx);
                    return Err(e);
                }
                Ok(placed)
            }
            Err(e) => {
                s.cancel_tx(&self.ctx, tx).unwrap();
                Err(e)
            }
        }
    }

    fn register_frame(
        &mut self,
        register: MediaRegister,
        name: String,
    ) -> Result<FrameRegistered, CmdError> {
        let mut s = self.state.lock().unwrap();
        let tx = s
            .begin_tx(&self.ctx, TxKind::Batch, "Add frame to media bin")?
            .id;
        let mut steps = TxSteps {
            state: &mut s,
            ctx: &self.ctx,
            tx,
        };
        let done = steps
            .run::<MediaRegistered>("media.register", &register)
            .and_then(|registered| {
                if registered.created {
                    steps.run::<Value>(
                        "media.rename",
                        &json!({"media": registered.media_id, "name": name}),
                    )?;
                }
                Ok(registered)
            });
        match done {
            Ok(registered) => {
                if let Err(e) = s.commit_tx(&self.ctx, tx) {
                    let _ = s.cancel_tx(&self.ctx, tx);
                    return Err(e);
                }
                let media = &s.doc().media[&registered.media_id];
                Ok(FrameRegistered {
                    registered,
                    path: media.path_abs.clone().unwrap_or_default(),
                    name: cutweave_ops::media::asset_name(media).into_owned(),
                })
            }
            Err(e) => {
                s.cancel_tx(&self.ctx, tx).unwrap();
                Err(e)
            }
        }
    }
}

/// The document commands of an import that is more than registrations, submitted into one open
/// transaction of the importing actor (as the engine does).
struct TxSteps<'a> {
    state: &'a mut DocState,
    ctx: &'a ActorCtx,
    tx: cutweave_commands::TxId,
}

impl TxSteps<'_> {
    fn run<T: serde::de::DeserializeOwned>(
        &mut self,
        name: &str,
        params: &impl serde::Serialize,
    ) -> Result<T, CmdError> {
        let params = serde_json::to_value(params).unwrap();
        let submit = Submit::new(self.ctx.clone(), name, params).in_tx(self.tx);
        let applied = self.state.submit(submit)?;
        Ok(serde_json::from_value(applied.output).unwrap())
    }
}

impl SlideshowSteps for TxSteps<'_> {
    fn doc(&self) -> Project {
        self.state.doc().clone()
    }

    fn register(&mut self, register: &MediaRegister) -> Result<MediaRegistered, CmdError> {
        self.run("media.register", register)
    }

    fn insert(
        &mut self,
        insert: &cutweave_ops::timeline::TimelineInsert,
    ) -> Result<cutweave_ops::timeline::TimelineInsertOutput, CmdError> {
        self.run("timeline.insert", insert)
    }
}

/// The relink commands' sink: `media.set_location` for each asset in one transaction on a
/// connection of its own, as the engine does.
struct RelinkTx {
    state: Arc<Mutex<DocState>>,
    ctx: ActorCtx,
}

impl RelinkSink for RelinkTx {
    fn relocate(&mut self, batch: Vec<MediaSetLocation>) -> Result<(), CmdError> {
        let mut s = self.state.lock().unwrap();
        let tx = s.begin_tx(&self.ctx, TxKind::Batch, "Relink media")?.id;
        for set in &batch {
            let params = serde_json::to_value(set).unwrap();
            let submit = Submit::new(self.ctx.clone(), "media.set_location", params).in_tx(tx);
            if let Err(e) = s.submit(submit) {
                s.cancel_tx(&self.ctx, tx).unwrap();
                return Err(e);
            }
        }
        if let Err(e) = s.commit_tx(&self.ctx, tx) {
            let _ = s.cancel_tx(&self.ctx, tx);
            return Err(e);
        }
        Ok(())
    }
}

struct Harness<'s> {
    registry: Arc<Registry>,
    state: Arc<Mutex<DocState>>,
    /// The `job.*` context, also running the analysis jobs of imports (never the document).
    jobs: JobManager,
    /// The `export.*` queue (never started: exports wait in line), on `jobs`.
    exports: ExportQueue<ExportPlan>,
    presets: Arc<PresetStore>,
    clock: Arc<ManualClock>,
    initial: Project,
    mirror: JsonMirror,
    events: Vec<DocEvent>,
    /// The connection of `user` and of `agent:prop` (a closed one never opens transactions
    /// again, so a reconnect gets a new one).
    conns: [u64; 2],
    log: Vec<String>,
    stats: &'s RefCell<Stats>,
}

fn truncated(v: &Value) -> String {
    let mut s = v.to_string();
    if s.len() > 240 {
        let cut = (0..=240)
            .rev()
            .find(|i| s.is_char_boundary(*i))
            .unwrap_or(0);
        s.truncate(cut);
        s.push('…');
    }
    s
}

/// Where two documents differ (as ops), for failure messages.
fn difference(from: &Project, to: &Project) -> String {
    match diff(from, to) {
        Ok(patch) => truncated(&serde_json::to_value(&patch).unwrap()),
        Err(e) => format!("(no field-level diff: {e})"),
    }
}

impl<'s> Harness<'s> {
    fn new(start: &Start, stats: &'s RefCell<Stats>) -> Harness<'s> {
        let initial = match start {
            Start::Generated(doc) => (**doc).clone(),
            Start::Empty | Start::Fixture => Project::new("Untitled"),
        };
        initial.validate().expect("starting documents are valid");
        let clock = Arc::new(ManualClock::new(WallTime::UNIX_EPOCH));
        let config = DocConfig::deterministic(Arc::clone(&REGISTRY), initial.clone(), SEED)
            .with_clock(Arc::clone(&clock) as Arc<dyn cutweave_commands::Clock>);
        let jobs = job_manager();
        let exports = testing::export_queue(&jobs);
        let mut h = Harness {
            registry: Arc::clone(&REGISTRY),
            state: Arc::new(Mutex::new(DocState::new(config))),
            jobs,
            exports,
            presets: Arc::default(),
            clock,
            mirror: JsonMirror::new(&initial, Rev::ZERO),
            initial,
            events: Vec::new(),
            conns: [1, 2],
            log: Vec::new(),
            stats,
        };
        if matches!(start, Start::Fixture) {
            h.build_fixture();
        }
        h
    }

    fn lock(&self) -> MutexGuard<'_, DocState> {
        self.state.lock().unwrap()
    }

    fn actor(&self, agent: bool) -> ActorCtx {
        if agent {
            ActorCtx::agent(ConnId::new(self.conns[1]), AGENT_LABEL).unwrap()
        } else {
            ActorCtx::ui(ConnId::new(self.conns[0]))
        }
    }

    fn observe(&self) -> Obs {
        let s = self.lock();
        Obs {
            rev: s.rev(),
            committed_rev: s.committed_rev(),
            live: s.doc().clone(),
            committed: s.committed_doc().clone(),
        }
    }

    /// Fails the case, with the requests that led here.
    fn fail(&self, msg: impl Display) -> ! {
        let from = self.log.len().saturating_sub(40);
        panic!(
            "{msg}\n--- requests {}..{} of this sequence ---\n{}",
            from + 1,
            self.log.len(),
            self.log[from..].join("\n")
        );
    }

    /// The WP-1B.06 edit fixture: three linked video/audio pairs on V1/A1, a still on V1 and a
    /// spare video track.
    fn build_fixture(&mut self) {
        let user = self.actor(false);
        let out = self.must(&user, "project.new", &json!({"name": "Fixture"}));
        let (seq, video) = (out["sequence"].clone(), out["video_track"].clone());
        let v = FakeProbe::video("/m/v.mp4", 10, true);
        let media = self.must(
            &user,
            "media.register",
            &json!({"path": "/m/v.mp4", "probe": v.probe, "content_hash": v.content_hash}),
        )["media_id"]
            .clone();
        for at in ["0s", "12s", "24s"] {
            self.must(
                &user,
                "timeline.insert",
                &json!({"sequence": seq, "track": video, "media": media, "at": at}),
            );
        }
        let i = FakeProbe::image("/m/i.png");
        let still = self.must(
            &user,
            "media.register",
            &json!({"path": "/m/i.png", "probe": i.probe, "content_hash": i.content_hash}),
        )["media_id"]
            .clone();
        self.must(
            &user,
            "timeline.insert",
            &json!({"sequence": seq, "track": video, "media": still, "at": "40s",
                   "duration": "3s"}),
        );
        self.must(
            &user,
            "track.add",
            &json!({"sequence": seq, "kind": "video"}),
        );
    }

    fn must(&mut self, ctx: &ActorCtx, name: &str, params: &Value) -> Value {
        match self.exec(ctx, name, params, false) {
            Ok(done) => done.output,
            Err(e) => self.fail(format!("setup: {name} failed: {e}")),
        }
    }

    fn import(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let importer = if *ctx.actor() == cutweave_commands::Actor::User {
            ActorCtx::ui(ConnId::new(1001))
        } else {
            ActorCtx::agent(ConnId::new(1002), AGENT_LABEL).unwrap()
        };
        let sink = ImportSink {
            state: Arc::clone(&self.state),
            ctx: importer,
        };
        // `media.import_frame` takes its frames from a store that sees the live document.
        let frames = Arc::new(FakeFrames::new(self.lock().doc().clone()));
        let mut ctx_any = ImportCtx::new(Arc::new(fake_probe()), Box::new(sink))
            .with_analysis(analyzer(&self.jobs))
            .with_frames(frames);
        self.registry
            .invoke_engine_json(name, params.clone(), &mut ctx_any, ctx.access())
    }

    /// Runs `export.start` against the committed document (the starter queues nothing).
    fn export(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let snapshot = Arc::new(self.lock().committed_snapshot());
        let mut ctx_any = testing::queue_ctx(snapshot, &self.exports);
        self.registry
            .invoke_engine_json(name, params.clone(), &mut ctx_any, ctx.access())
    }

    /// Runs an export preset command (WP-2G.01) against the committed document and the
    /// harness's in-memory preset store.
    fn preset(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let snapshot = Arc::new(self.lock().committed_snapshot());
        let mut call = testing::preset_ctx(Arc::clone(&self.presets), snapshot);
        self.registry
            .invoke_engine_json(name, params.clone(), &mut call, ctx.access())
    }

    /// Runs a proxy command (WP-2F.01) against a service that makes none: proxies are cache
    /// state, so the document never changes.
    fn proxy(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let mut call = ProxyCall {
            service: Some(Arc::new(testing::NoProxies)),
            doc: self.lock().snapshot().doc.clone(),
        };
        self.registry
            .invoke_engine_json(name, params.clone(), &mut call, ctx.access())
    }

    /// Runs a collect command (WP-2F.04) against the committed document and a disk that
    /// holds nothing: the open document never changes.
    fn collect(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let mut call = cutweave_ops::project::collect::CollectCtx {
            doc: self.lock().committed_snapshot().doc.clone(),
            project_root: None,
            allowed_roots: None,
            jobs: self.jobs.clone(),
            host: Arc::new(testing::NoDisk),
        };
        self.registry
            .invoke_engine_json(name, params.clone(), &mut call, ctx.access())
    }

    /// Runs a relink command (WP-2F.03) against a disk that holds the import files; what it
    /// finds is committed in one transaction on a connection of its own.
    fn relink(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let relinker = if *ctx.actor() == cutweave_commands::Actor::User {
            ActorCtx::ui(ConnId::new(1003))
        } else {
            ActorCtx::agent(ConnId::new(1004), AGENT_LABEL).unwrap()
        };
        let mut call = RelinkCtx {
            doc: self.lock().snapshot().doc.clone(),
            prober: Arc::new(fake_probe()),
            files: Arc::new(testing::fake_files()),
            sink: Some(Box::new(RelinkTx {
                state: Arc::clone(&self.state),
                ctx: relinker,
            })),
            policy: ImportPolicy::default(),
        };
        self.registry
            .invoke_engine_json(name, params.clone(), &mut call, ctx.access())
    }

    /// Runs `audio.get_levels` (WP-2E.02) against an analyzer that hears silence: measuring
    /// never changes the document.
    fn levels(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let mut call = LevelsCtx {
            snapshot: Arc::new(self.lock().snapshot()),
            analyzer: Some(Arc::new(Silence)),
        };
        self.registry
            .invoke_engine_json(name, params.clone(), &mut call, ctx.access())
    }

    /// Runs a `job.*` command against the job manager.
    fn job(&self, ctx: &ActorCtx, name: &str, params: &Value) -> Result<Value, CmdError> {
        let mut jobs = self.jobs.clone();
        self.registry
            .invoke_engine_json(name, params.clone(), &mut jobs, ctx.access())
    }

    /// Takes the events of the last request, replays them onto the mirror and checks the
    /// properties every state must have. Returns whether a `doc.patched` was among them.
    fn absorb(&mut self, what: &str, after: &Obs) -> bool {
        let (events, verified, live_open) = {
            let mut s = self.lock();
            let _ = s.take_changes();
            let live_open = s.transactions().iter().any(|t| t.kind.is_live());
            (s.take_events(), s.verify(), live_open)
        };
        if let Err(e) = verified {
            self.fail(format!("(5) {what}: DocState::verify: {e}"));
        }
        // (6) The mirror follows from events only.
        for event in &events {
            if let Err(e) = self.mirror.apply(event) {
                self.fail(format!("(6) {what}: an event does not replay: {e}"));
            }
        }
        if self.mirror.rev() != after.rev {
            self.fail(format!(
                "(6) {what}: the mirror is at rev {}, the document at rev {}",
                self.mirror.rev(),
                after.rev
            ));
        }
        let json = serde_json::to_value(&after.live).unwrap();
        if !cutweave_commands::json_eq(self.mirror.json(), &json) {
            self.fail(format!(
                "(6) {what}: the JSON mirror differs from the live document"
            ));
        }
        // (4) The live document survives a JSON round trip.
        match serde_json::from_value::<Project>(json) {
            Ok(back) if back == after.live => {}
            Ok(back) => self.fail(format!(
                "(4) {what}: the deserialized document differs: {}",
                difference(&after.live, &back)
            )),
            Err(e) => self.fail(format!(
                "(4) {what}: the document does not deserialize: {e}"
            )),
        }
        // (5) Invariants.
        if let Err(e) = check_invariants(&after.committed) {
            self.fail(format!("(5) {what}: committed document: {e}"));
        }
        if !live_open && let Err(e) = check_invariants(&after.live) {
            self.fail(format!("(5) {what}: live document: {e}"));
        }
        let patched = events.iter().any(|e| e.as_patched().is_some());
        self.events.extend(events);
        patched
    }

    /// Runs one request and checks properties 3–6 (and 1–2 at the patch level).
    #[allow(clippy::too_many_lines)]
    fn exec(
        &mut self,
        ctx: &ActorCtx,
        name: &str,
        params: &Value,
        in_tx: bool,
    ) -> Result<Done, CmdError> {
        let entry = self
            .registry
            .get(name)
            .unwrap_or_else(|| panic!("`{name}` is not registered"));
        let (kind, read_only, context) = (
            entry.kind(),
            entry.meta.annotations.read_only,
            entry.engine_context(),
        );
        let before = self.observe();
        let tx = if in_tx && kind != EntryKind::Engine {
            self.lock().transaction_of(ctx.conn()).map(|t| t.id)
        } else {
            None
        };
        let result = match context {
            Some(c) if c == TypeId::of::<ImportCtx>() => {
                self.import(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c == TypeId::of::<JobManager>() => {
                self.job(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c == TypeId::of::<ExportCtx>() => {
                self.export(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c == TypeId::of::<PresetCtx>() => {
                self.preset(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c == TypeId::of::<ProxyCall>() => {
                self.proxy(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c == TypeId::of::<cutweave_ops::project::collect::CollectCtx>() => {
                self.collect(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c == TypeId::of::<RelinkCtx>() => {
                self.relink(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c == TypeId::of::<LevelsCtx>() => {
                self.levels(ctx, name, params).map(|output| Done {
                    output,
                    applied: None,
                })
            }
            Some(c) if c != TypeId::of::<DocState>() => {
                panic!("the harness cannot run `{name}`: teach it that engine context")
            }
            _ => {
                let mut submit = Submit::new(ctx.clone(), name, params.clone());
                if let Some(tx) = tx {
                    submit = submit.in_tx(tx);
                }
                let applied = self.lock().submit(submit);
                applied.map(|a| Done {
                    output: a.output.clone(),
                    applied: Some(a),
                })
            }
        };
        let after = self.observe();
        let outcome = match &result {
            Ok(_) => "ok".to_owned(),
            Err(e) => format!("{}: {e}", e.code()),
        };
        self.log.push(format!(
            "#{:<3} {:<12} {name}{} {} -> {}",
            self.log.len() + 1,
            ctx.actor().to_string(),
            tx.map_or_else(String::new, |t| format!(" [in {t}]")),
            truncated(params),
            outcome.chars().take(200).collect::<String>()
        ));
        let what = format!("{name} {}", truncated(params));
        let patched = self.absorb(&what, &after);
        match &result {
            Err(e) => {
                // A UI-only entry (`edit.set_history_limit`) refuses every other credential.
                let ui_only = e.code() == "forbidden"
                    && self
                        .registry
                        .get(name)
                        .is_some_and(|entry| !ctx.access().allows(entry.meta.scope));
                if !ui_only
                    && !matches!(
                        e.code(),
                        "invalid" | "not_found" | "locked" | "conflict" | "unsupported"
                    )
                {
                    self.fail(format!("{what}: unexpected error `{}`: {e}", e.code()));
                }
                // (3) A failure changes nothing.
                if after != before || patched {
                    self.fail(format!(
                        "(3) {what} failed ({e}) but changed the document: {}",
                        difference(&before.live, &after.live)
                    ));
                }
            }
            Ok(done) => {
                if (kind == EntryKind::Query || read_only) && (after != before || patched) {
                    self.fail(format!("{what}: a read-only request changed the document"));
                }
                if tx.is_none() && after.committed != before.committed {
                    self.check_committed_change(&what, name, params, done, &before, &after);
                }
            }
        }
        result
    }

    /// (1)/(2) at the patch level and the linked-group rules, for a request that committed.
    fn check_committed_change(
        &self,
        what: &str,
        name: &str,
        params: &Value,
        done: &Done,
        before: &Obs,
        after: &Obs,
    ) {
        if let Some(a) = done.applied.as_ref().filter(|a| a.tx_id.is_some()) {
            match apply_patch(&before.committed, &a.ops) {
                Ok(doc) if doc == after.committed => {}
                Ok(doc) => self.fail(format!(
                    "(2) {what}: its patch does not reproduce the change: {}",
                    difference(&after.committed, &doc)
                )),
                Err(e) => self.fail(format!("(2) {what}: its patch does not apply: {e}")),
            }
            match apply_patch(&after.committed, &a.ops.invert()) {
                Ok(doc) if doc == before.committed => {}
                Ok(doc) => self.fail(format!(
                    "(1) {what}: its inverse patch does not restore the document: {}",
                    difference(&before.committed, &doc)
                )),
                Err(e) => self.fail(format!("(1) {what}: its inverse patch does not apply: {e}")),
            }
        }
        if let Err(e) = check_linked_edit(
            name,
            params,
            &done.output,
            &before.committed,
            &after.committed,
        ) {
            self.fail(format!("(5) {what}: linked groups: {e}"));
        }
    }

    /// (1) and (2) through the history: right after a request that committed a change, the
    /// inverse history move restores the previous committed document and the forward one the
    /// changed document again. Skipped while transactions are open (their undo may
    /// legitimately conflict with them).
    fn check_history(&mut self, ctx: &ActorCtx, name: &str, params: &Value, before: &Obs) {
        let after = self.observe();
        if after.committed == before.committed || !self.lock().transactions().is_empty() {
            return;
        }
        let top = self
            .lock()
            .history_page(1, None, None)
            .unwrap()
            .entries
            .into_iter()
            .next();
        let Some(top) = top else {
            self.fail(format!(
                "{name} committed a change but left no history entry"
            ));
        };
        if top.rev != after.committed_rev {
            self.fail(format!(
                "{name}: the newest history entry is at rev {}, the document at {}",
                top.rev, after.committed_rev
            ));
        }
        let (back, forth, scope) = match top.cause {
            EntryCause::Undo { .. } => ("edit.redo", "edit.undo", params.clone()),
            EntryCause::Redo { .. } => ("edit.undo", "edit.redo", params.clone()),
            _ if top.actor != *ctx.actor() => self.fail(format!(
                "{name} by {} logged a change by {}",
                ctx.actor(),
                top.actor
            )),
            _ if !top.can_undo => return,
            _ => ("edit.undo", "edit.redo", json!({})),
        };
        self.stats.borrow_mut().history_checks += 1;
        if let Err(e) = self.exec(ctx, back, &scope, false) {
            self.fail(format!("(1) {back} right after {name} failed: {e}"));
        }
        let undone = self.observe();
        if undone.committed != before.committed {
            self.fail(format!(
                "(1) undo(apply(doc)) != doc: {back} after {name} does not restore the document: {}",
                difference(&before.committed, &undone.committed)
            ));
        }
        if let Err(e) = self.exec(ctx, forth, &scope, false) {
            self.fail(format!("(2) {forth} after {back} of {name} failed: {e}"));
        }
        let redone = self.observe();
        if redone.committed != after.committed {
            self.fail(format!(
                "(2) redo(undo(apply)) != apply: {forth} after {back} of {name} does not restore \
                 the change: {}",
                difference(&after.committed, &redone.committed)
            ));
        }
    }

    fn step(&mut self, step: &Step) {
        let index = usize::from(step.agent);
        let ctx = self.actor(step.agent);
        match step.action {
            Action::Disconnect => {
                let closed = self.lock().close_connection(ctx.conn());
                self.conns[index] += 2;
                self.log.push(format!(
                    "#{:<3} {} disconnects ({} transaction(s) rolled back)",
                    self.log.len() + 1,
                    ctx.actor(),
                    closed.len()
                ));
                let after = self.observe();
                self.absorb("disconnect", &after);
            }
            Action::Idle => {
                self.clock.advance(StdDuration::from_secs(31));
                let expired = self.lock().expire_idle();
                self.log.push(format!(
                    "#{:<3} 31 s pass ({} gesture(s) expired)",
                    self.log.len() + 1,
                    expired.len()
                ));
                let after = self.observe();
                self.absorb("idle", &after);
            }
            Action::Request { seed, in_tx } => {
                let doc = self.lock().doc().clone();
                let (name, params) = generate(&self.registry, &doc, seed);
                let before = self.observe();
                let result = self.exec(&ctx, &name, &params, in_tx);
                self.stats
                    .borrow_mut()
                    .record(&name, result.as_ref().map(drop));
                if result.is_ok() {
                    self.check_history(&ctx, &name, &params, &before);
                }
                let items = self.lock().doc().item_count();
                let mut stats = self.stats.borrow_mut();
                stats.max_items = stats.max_items.max(items);
            }
        }
    }

    /// End of a sequence: (6) from the initial document, (4) through the file format, and
    /// closing every connection leaves the committed document.
    fn finish(&mut self) {
        let now = self.observe();
        match replay_events(&self.initial, Rev::ZERO, &self.events) {
            Ok(m) if m.rev() == now.rev && m.matches(&now.live) => {}
            Ok(m) => self.fail(format!(
                "(6) replaying all {} events from the initial document gives rev {} and a \
                 different document than rev {}",
                self.events.len(),
                m.rev(),
                now.rev
            )),
            Err(e) => self.fail(format!("(6) the event stream does not replay: {e}")),
        }
        for (which, doc) in [("committed", &now.committed), ("live", &now.live)] {
            let text = to_document_string(doc).unwrap();
            match open_str(&text) {
                Ok(OpenOutcome::Editable { project, report })
                    if !report.migrated()
                        && project == *doc
                        && to_document_string(&project).unwrap() == text => {}
                Ok(_) => self.fail(format!(
                    "(4) the {which} document does not round-trip through its file text"
                )),
                Err(e) => self.fail(format!(
                    "(4) the {which} document's file text does not open: {e}"
                )),
            }
        }
        for agent in [false, true] {
            let conn = self.actor(agent).conn();
            self.lock().close_connection(conn);
        }
        let after = self.observe();
        self.absorb("closing every connection", &after);
        // (After a rollback `rev` stays ahead of `committed_rev`; only the documents must agree.)
        if after.live != after.committed {
            self.fail(format!(
                "with every connection closed, the live document is not the committed one: {}",
                difference(&after.committed, &after.live)
            ));
        }
    }
}

fn run_case(start: &Start, steps: &[Step], stats: &RefCell<Stats>) {
    let mut h = Harness::new(start, stats);
    for step in steps {
        h.step(step);
    }
    h.finish();
    stats.borrow_mut().cases += 1;
}

fn run(runner: &mut TestRunner, stats: &RefCell<Stats>) {
    let result = runner.run(&arb_case(), |(start, steps)| {
        run_case(&start, &steps, stats);
        Ok(())
    });
    if let Err(e) = result {
        panic!("{e}");
    }
}

