#[test]
fn random_request_sequences_keep_every_property() {
    let config = Config {
        failure_persistence: Some(Box::new(FileFailurePersistence::Direct(REGRESSIONS))),
        max_shrink_iters: 2048,
        ..Config::default()
    };
    let stats = RefCell::new(Stats::default());
    run(&mut TestRunner::new(config), &stats);
    println!("{}", stats.borrow().report(&REGISTRY));
}

/// The strategy coverage report (`--no-capture` prints it): a fixed-seed run, so the numbers
/// only change when the strategies or the commands do.
#[test]
fn strategy_coverage_report() {
    let config = Config {
        cases: COVERAGE_CASES,
        failure_persistence: None,
        ..Config::default()
    };
    let stats = RefCell::new(Stats::default());
    run(
        &mut TestRunner::new_with_rng(config, TestRng::deterministic_rng(RngAlgorithm::ChaCha)),
        &stats,
    );
    let stats = stats.borrow();
    let report = stats.report(&REGISTRY);
    println!("{report}");
    let (exercised, total) = stats.coverage(&REGISTRY);
    assert!(
        exercised * 100 >= total * 95,
        "fewer than 95% of the entries were applied successfully:\n{report}"
    );
}

#[test]
fn every_registered_entry_has_a_property_strategy() {
    let missing: Vec<String> = testing::missing_strategies(&REGISTRY)
        .into_iter()
        .map(|name| format!("missing property strategy for {name}"))
        .collect();
    assert!(missing.is_empty(), "{}", missing.join("\n"));
    assert!(testing::covered(&REGISTRY).count() >= 32);
    for job in ["job.status", "job.list", "job.wait", "job.cancel"] {
        assert!(
            testing::covered(&REGISTRY).any(|e| e.name() == job),
            "{job}"
        );
    }
}

